-- =====================================================================
-- TeamPulse 演示数据种子（**仅用于演示/测试环境，不要在生产执行**）
--
-- 来源：开发库（含 8 个演示账号、2 支团队、日程、日志、评论、打卡记录等）
-- 特性：
--   1) 全部用 INSERT IGNORE，重复执行不会报错、不会覆盖已有行
--   2) 不含管理员账号（容器启动时由 BootstrapDataInitializer 创建，密码来自 .env）
--   3) 已剔除开发期的垃圾数据（设备 1111、tp_probe_user）
--   4) 所有 64 位十六进制串已替换为 demo-xxxx：message_id 仍唯一；
--      设备 secret 变成占位值，导入后请用「轮换密钥」接口生成真实密钥再让设备上报
--
-- 用法（容器环境）：
--   docker exec -i tp-mysql mysql -uroot -p<密码> teampulse < deploy/sql/seed-demo.sql
--
-- 演示账号（登录密码统一 123456）：
--   zhangsan 部门经理 / lisi 普通员工 / wangwu 团队负责人
--   sunqi 人事专员 / zhaoliu 审计专员 / zhouba 普通员工 / wujiu 普通员工
-- =====================================================================
SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS = 0;

