INSERT  IGNORE INTO `worklog` (`worklog_id`, `title`, `content`, `log_date`, `creator_id`, `related_schedule_id`, `related_team_id`, `created_at`, `updated_at`, `deleted`) VALUES (1,'第 12 次 迭代评审纪要','确认考勤汇总口径：按工作日 09:00-18:00 计算，迟到宽限 5 分钟，早退同理。','2026-10-20',1,1,1,'2026-10-26 17:28:15','2026-10-26 20:01:53',0),(2,'ESP32 串口驱动排查记录','本机安装 CH340 驱动后 COM 口正常识别，MQTT 上行报文 HMAC 签名校验通过，重放被正确拒绝。','2026-10-21',2,2,2,'2026-10-26 17:28:15','2026-10-26 17:28:15',0),(3,'索引优化实验','attendance_daily 补 (user_id, work_date) 唯一键后，日汇总查询从 120ms 降到 8ms。','2026-10-22',1,3,1,'2026-10-26 17:28:15','2026-10-26 17:28:15',0),(4,'看板拖拽实现笔记','采用 HTML5 draggable + 乐观更新，列内排序按 sort_order 以 1000 为步长递增，冲突以服务端为准。','2026-10-23',3,4,1,'2026-10-26 17:28:15','2026-10-26 17:28:15',0),(5,'本周工时小结','团队累计 236 小时，迟到 2 次，均已补卡说明。','2026-10-24',2,NULL,2,'2026-10-26 17:28:15','2026-10-26 17:28:15',0),(7,'今日','123','2026-10-25',1,NULL,NULL,'2026-10-26 19:20:14','2026-10-26 19:20:14',0),(8,'硬件联调复盘','串口时序导致丢包，改成中断接收后稳定。','2026-10-26',2,NULL,NULL,'2026-10-26 20:51:57','2026-10-26 20:51:57',0),(9,'接口压测报告','MQTT 上报 1000 QPS 下 P99 延迟 38ms。','2026-10-26',3,NULL,NULL,'2026-10-26 20:51:58','2026-10-26 20:51:58',0),(10,'前端样式统一','卡片改淡蓝主题，对比度提升。','2026-10-26',4,NULL,NULL,'2026-10-26 20:51:58','2026-10-26 20:51:58',0),(11,'考勤规则调整记录','迟到宽限从 5 分钟改为 10 分钟。','2026-10-22',6,NULL,NULL,'2026-10-26 20:51:58','2026-10-26 20:51:58',0);
